// src/lib/server/db.ts
import postgres from 'postgres';
import { env } from '$env/dynamic/private';

type Sql = ReturnType<typeof postgres>;

let _sql: Sql | null = null;
function client(): Sql {
    if (!_sql) {
        if (!env.DATABASE_URL) throw new Error('DATABASE_URL is not set');
        _sql = postgres(env.DATABASE_URL, { ssl: 'require' });
    }
    return _sql;
}

// Lazy proxy: the connection (and the env-var check) happens on FIRST USE, not at
// import time. This keeps the module safe to import during the build's route
// analysis, where DATABASE_URL isn't set. `sql\`...\`` and `sql.json(...)` both work.
export const sql = new Proxy(function () {} as unknown as Sql, {
    apply(_target, _thisArg, args: any[]) {
        return (client() as any)(...args);
    },
    get(_target, prop) {
        const c = client() as any;
        const value = c[prop];
        return typeof value === 'function' ? value.bind(c) : value;
    }
}) as Sql;

// src/lib/server/football.ts
import { env } from '$env/dynamic/private';
import { tlaToId } from '$lib/plTeams';

const BASE = 'https://api.football-data.org/v4';

export interface Fixture {
    id: string;
    matchweek: number;
    kickoff: string;
    status: string;
    homeId: string;
    awayId: string;
    homeName: string;
    awayName: string;
    winner: string | null;
    homeGoals: number | null; // null until the match has a score to report
    awayGoals: number | null;
}

export type FormResult = 'W' | 'D' | 'L';

// One match in a club's recent form. Carries enough to explain the result on
// hover -- who it was against, the score from THIS club's point of view, and
// which ground -- rather than just the letter.
export interface FormEntry {
    result: FormResult;
    opponentId: string;
    home: boolean;
    gf: number; // goals for, from this club's perspective
    ga: number;
    kickoff: string;
}

export interface StandingRow {
    teamId: string;
    name: string;
    crest: string | null; // club badge URL from football-data; null if unavailable
    played: number;
    won: number;
    drawn: number;
    lost: number;
    gd: number;
    points: number;
    form: FormEntry[]; // last 5 matches, MOST RECENT FIRST; shorter early in the season
    formPoints: number; // points won across those matches (0-15)
}

export interface FinishedMatch {
    id: string;
    matchweek: number;
    kickoff: string;
    winner: string;
    homeId: string;
    awayId: string;
    homeGoals: number | null;
    awayGoals: number | null;
}

// A match as the schedule knows it, whether or not it has been played.
export interface ScheduledMatch {
    id: string;
    matchweek: number;
    kickoff: string;
    status: string;
    played: boolean;
    homeId: string;
    awayId: string;
}

export interface UpcomingMatch {
    id: string;
    matchweek: number;
    kickoff: string;
    homeId: string;
    awayId: string;
}

const cache = new Map<string, { at: number; data: any }>();
const TTL_MS = 60 * 1000;

async function fd(path: string): Promise<any> {
    const hit = cache.get(path);
    if (hit && Date.now() - hit.at < TTL_MS) return hit.data;
    if (!env.FOOTBALL_DATA_TOKEN) throw new Error('FOOTBALL_DATA_TOKEN is not set');
    const res = await fetch(`${BASE}${path}`, { headers: { 'X-Auth-Token': env.FOOTBALL_DATA_TOKEN } });
    if (!res.ok) throw new Error(`football-data ${res.status} on ${path}`);
    const data = await res.json();
    cache.set(path, { at: Date.now(), data });
    return data;
}

// EVERY match in the season, fully mapped, from a single cached call.
//
// /competitions/PL/matches returns all 380 fixtures across all 38 matchdays with
// every field below, so the per-week, whole-season and finished-only lists are all
// just filters over this. They used to be four different API paths -- and because
// `?matchday=N` is a distinct cache key per week, paging through the season was one
// upstream request per week and tripped football-data's 10-per-minute limit around
// week 11.
async function allMatches(): Promise<Fixture[]> {
    const data = await fd('/competitions/PL/matches');
    return (data.matches ?? []).map((m: any) => ({
        id: String(m.id),
        matchweek: m.matchday,
        kickoff: m.utcDate,
        status: m.status,
        homeId: tlaToId(m.homeTeam.tla),
        awayId: tlaToId(m.awayTeam.tla),
        homeName: m.homeTeam.shortName || m.homeTeam.name,
        awayName: m.awayTeam.shortName || m.awayTeam.name,
        winner: m.score?.winner ?? null,
        homeGoals: m.score?.fullTime?.home ?? null,
        awayGoals: m.score?.fullTime?.away ?? null
    }));
}

export async function getFixtures(matchweek: number): Promise<Fixture[]> {
    // Sorted explicitly rather than trusting the upstream order, so a week's cards
    // always appear earliest-first.
    return (await allMatches())
        .filter((m) => m.matchweek === matchweek)
        .sort((a, b) => a.kickoff.localeCompare(b.kickoff));
}

// Last-5 form per club, most recent first. Derived from finished matches rather
// than football-data's `form` field, which is absent on some plans and doesn't
// document which end is most recent. Ordered by kickoff rather than matchweek, so
// a postponed game counts as recent when it was actually played.
function formGuide(matches: FinishedMatch[]): Map<string, { form: FormEntry[]; points: number }> {
    const played = new Map<string, { at: number; entry: FormEntry }[]>();
    const add = (teamId: string, at: number, entry: FormEntry) => {
        const list = played.get(teamId);
        if (list) list.push({ at, entry });
        else played.set(teamId, [{ at, entry }]);
    };

    for (const m of matches) {
        if (m.homeGoals == null || m.awayGoals == null) continue;
        const at = new Date(m.kickoff).getTime();
        if (!Number.isFinite(at)) continue;
        const home: FormResult = m.homeGoals > m.awayGoals ? 'W' : m.homeGoals < m.awayGoals ? 'L' : 'D';
        // Goals are stored per club rather than per fixture, so each side reads its
        // own row as "we scored gf, they scored ga" with no perspective flipping
        // left to the UI.
        add(m.homeId, at, {
            result: home,
            opponentId: m.awayId,
            home: true,
            gf: m.homeGoals,
            ga: m.awayGoals,
            kickoff: m.kickoff
        });
        add(m.awayId, at, {
            result: home === 'W' ? 'L' : home === 'L' ? 'W' : 'D',
            opponentId: m.homeId,
            home: false,
            gf: m.awayGoals,
            ga: m.homeGoals,
            kickoff: m.kickoff
        });
    }

    const guide = new Map<string, { form: FormEntry[]; points: number }>();
    for (const [teamId, list] of played) {
        const form = list.sort((a, b) => b.at - a.at).slice(0, 5).map((e) => e.entry);
        const points = form.reduce((n, e) => n + (e.result === 'W' ? 3 : e.result === 'D' ? 1 : 0), 0);
        guide.set(teamId, { form, points });
    }
    return guide;
}

export async function getStandings(): Promise<StandingRow[]> {
    const data = await fd('/competitions/PL/standings');
    // The form guide is a second upstream call. If it fails, still return the
    // table — losing form is a missing column, losing the table is a blank tab.
    let guide = new Map<string, { form: FormEntry[]; points: number }>();
    try {
        guide = formGuide(await getFinishedMatches());
    } catch (err) {
        console.error('standings: form guide unavailable, returning table without it', err);
    }
    const total = (data.standings ?? []).find((s: any) => s.type === 'TOTAL') ?? data.standings?.[0];
    return (total?.table ?? []).map((r: any) => {
        const teamId = tlaToId(r.team.tla);
        const f = guide.get(teamId);
        return {
            teamId,
            name: r.team.shortName || r.team.name,
            crest: r.team.crest ?? null,
            played: r.playedGames,
            won: r.won,
            drawn: r.draw,
            lost: r.lost,
            gd: r.goalDifference,
            points: r.points,
            form: f?.form ?? [],
            formPoints: f?.points ?? 0
        };
    });
}

// Every match in the season, played or not. The leaderboard needs the whole
// schedule to tell a matchweek that is over from one that is still being played.
export async function getSeasonMatches(): Promise<ScheduledMatch[]> {
    return (await allMatches()).map((m) => ({
        id: m.id,
        matchweek: m.matchweek,
        kickoff: m.kickoff,
        status: m.status,
        played: m.status === 'FINISHED' || m.status === 'AWARDED',
        homeId: m.homeId,
        awayId: m.awayId
    }));
}

export async function getFinishedMatches(): Promise<FinishedMatch[]> {
    // Exactly what ?status=FINISHED returned: AWARDED is deliberately NOT included,
    // matching the previous behaviour rather than getSeasonMatches' broader `played`.
    return (await allMatches())
        .filter((m) => m.status === 'FINISHED')
        .map((m) => ({
            id: m.id,
            matchweek: m.matchweek,
            kickoff: m.kickoff,
            winner: m.winner ?? 'DRAW',
            homeId: m.homeId,
            awayId: m.awayId,
            homeGoals: m.homeGoals,
            awayGoals: m.awayGoals
        }));
}

// Matches within a date window relative to now: `daysBack` days in the past to
// `daysAhead` days in the future. Used by the cron jobs to find recently-finished
// kickoffs (backward) and matches coming up soon (forward).
export async function getMatchesInWindow(daysBack = 0, daysAhead = 10): Promise<UpcomingMatch[]> {
    const from = new Date(Date.now() - daysBack * 86400000).toISOString().slice(0, 10);
    const to = new Date(Date.now() + daysAhead * 86400000).toISOString().slice(0, 10);
    const data = await fd(`/competitions/PL/matches?dateFrom=${from}&dateTo=${to}`);
    return (data.matches ?? []).map((m: any) => ({
        id: String(m.id),
        matchweek: m.matchday,
        kickoff: m.utcDate,
        homeId: tlaToId(m.homeTeam.tla),
        awayId: tlaToId(m.awayTeam.tla)
    }));
}

// Matches in a forward date window, used to map odds events to fixture ids.
export async function getUpcomingMatches(daysAhead = 10): Promise<UpcomingMatch[]> {
    return getMatchesInWindow(0, daysAhead);
}

// src/lib/server/odds.ts
import { env } from '$env/dynamic/private';
import { TEAMS } from '$lib/plTeams';

const ODDS_BASE = 'https://api.the-odds-api.com/v4';
const SPORT = 'soccer_epl';

function normalize(s: string): string {
    return s
        .toLowerCase()
        .replace(/&/g, 'and')
        .replace(/[^a-z ]/g, '')
        .replace(/\b(fc|afc)\b/g, '')
        .replace(/\s+/g, ' ')
        .trim();
}

const ALIASES: Record<string, string> = {
    // add here only if a club refuses to match, e.g. 'spurs': 'tot'
};
export function resolveTeamId(name: string): string | null {
    const n = normalize(name);
    if (ALIASES[n]) return ALIASES[n];
    for (const t of TEAMS) if (normalize(t.name) === n) return t.id;
    for (const t of TEAMS) {
        const tokens = normalize(t.name).split(' ');
        if (tokens.every((tok) => n.includes(tok))) return t.id;
    }
    return null;
}

export interface OddsMultipliers {
    homeId: string;
    awayId: string;
    commenceTime: string;
    probHome: number; // de-vigged fair probabilities (sum to 1)
    probDraw: number;
    probAway: number;
    multHome: number; // points multiplier 1 / (P_win + 0.5 * P_tie)
    multAway: number;
}

export async function fetchOddsMultipliers(): Promise<OddsMultipliers[]> {
    if (!env.ODDS_API_KEY) throw new Error('ODDS_API_KEY is not set');
    const url = `${ODDS_BASE}/sports/${SPORT}/odds?regions=uk&markets=h2h&oddsFormat=decimal&apiKey=${env.ODDS_API_KEY}`;
    const res = await fetch(url);
    if (!res.ok) throw new Error(`odds api ${res.status}: ${await res.text()}`);
    const events: any[] = await res.json();

    const out: OddsMultipliers[] = [];
    for (const ev of events) {
        const homeId = resolveTeamId(ev.home_team);
        const awayId = resolveTeamId(ev.away_team);
        if (!homeId || !awayId) continue;

        let sumH = 0,
            sumD = 0,
            sumA = 0,
            books = 0;
        for (const bk of ev.bookmakers ?? []) {
            const market = (bk.markets ?? []).find((m: any) => m.key === 'h2h');
            if (!market) continue;
            const oc = market.outcomes ?? [];
            const priceOf = (teamName: string) => oc.find((x: any) => x.name === teamName)?.price;
            const dh = priceOf(ev.home_team);
            const da = priceOf(ev.away_team);
            const dd = oc.find((x: any) => x.name === 'Draw')?.price;
            if (!dh || !da || !dd) continue;
            sumH += 1 / dh;
            sumD += 1 / dd;
            sumA += 1 / da;
            books++;
        }
        if (books === 0) continue;

        // Average implied probs across books, then de-vig (normalize to sum 1).
        const qH = sumH / books,
            qD = sumD / books,
            qA = sumA / books;
        const total = qH + qD + qA;
        const pH = qH / total,
            pD = qD / total,
            pA = qA / total;

        out.push({
            homeId,
            awayId,
            commenceTime: ev.commence_time,
            probHome: pH,
            probDraw: pD,
            probAway: pA,
            multHome: 1 / (pH + 0.5 * pD),
            multAway: 1 / (pA + 0.5 * pD)
        });
    }
    return out;
}

// src/routes/api/auth/register/+server.ts
import { json } from '@sveltejs/kit';
import { dev } from '$app/environment';
import { sql } from '$lib/server/db';
import { hashPassword, createSession } from '$lib/server/auth';
import type { RequestHandler } from './$types';

// Invite-bound signup. The email comes from the invite (locked), the person
// chooses username + password. Invite consumed atomically -> one link, one account.
export const POST: RequestHandler = async ({ request, cookies }) => {
    const { invite, username, password } = await request.json();
    const uname = (username ?? '').trim(); // keep original casing for display
    if (!invite) return json({ ok: false, error: 'An invite is required.' }, { status: 400 });
    if (uname.length < 2 || (password ?? '').length < 4) {
        return json({ ok: false, error: 'Username needs 2+ chars, password needs 4+.' }, { status: 400 });
    }

    const inv = (await sql`select email from invites where token = ${invite} and used_by is null`)[0];
    if (!inv || !inv.email) {
        return json({ ok: false, error: 'This invite link is invalid or already used.' }, { status: 409 });
    }
    const email = String(inv.email).toLowerCase();

    if ((await sql`select 1 from users where email = ${email}`)[0]) {
        return json({ ok: false, error: 'An account already exists for this email.' }, { status: 409 });
    }
    if ((await sql`select 1 from users where lower(username) = ${uname.toLowerCase()}`)[0]) {
        return json({ ok: false, error: 'That username is taken — pick another.' }, { status: 409 });
    }

    const passwordHash = await hashPassword(password);
    let userId: number;
    try {
        userId = await sql.begin(async (tx) => {
            const u = (await tx`
                insert into users (email, username, password_hash)
                values (${email}, ${uname}, ${passwordHash}) returning id`)[0];
            const claimed = await tx`
                update invites set used_by = ${Number(u.id)}, used_at = now()
                where token = ${invite} and used_by is null returning token`;
            if (claimed.length === 0) throw new Error('INVALID_INVITE');
            return Number(u.id);
        });
    } catch (e: any) {
        if (e?.message === 'INVALID_INVITE') {
            return json({ ok: false, error: 'This invite link is invalid or already used.' }, { status: 409 });
        }
        if (e?.code === '23505') {
            return json({ ok: false, error: 'That username is taken — pick another.' }, { status: 409 });
        }
        throw e;
    }

    const { token, expiresAt } = await createSession(userId);
    cookies.set('session', token, { path: '/', httpOnly: true, secure: !dev, sameSite: 'lax', expires: expiresAt });
    return json({ ok: true });
};

// Shared bracket structure and utilities for March Madness

// Scoring constants (use let so they can be updated from config)
export let SCORE_FOR_ROUND = [0, 10, 20, 30, 50, 80, 130];
export let SEED_FACTOR = [0, 1, 2, 3, 4, 5, 6];
export let ROUND_NAMES = ["", "Round of 64", "Round of 32", "Sweet 16", "Elite 8", "Final Four", "Championship"];
export let STAR_BONUS = [25, 20, 15, 10, 5];
export let SCORE_DIFF_BUCKETS = [5, 10];  // Buckets for categorizing score differentials

// Track if config has been loaded
let configLoaded = false;

/**
 * Load scoring configuration from a JSON file.
 * Updates SCORE_FOR_ROUND, SEED_FACTOR, ROUND_NAMES, and STAR_BONUS from the config.
 */
export async function loadScoringConfig(configPath = '/marchMadness/2026/scoring-config.json') {
    if (configLoaded) {
        return true;  // Already loaded
    }
    
    try {
        const response = await fetch(configPath);
        if (!response.ok) {
            console.warn(`Could not load scoring config from ${configPath}, using defaults`);
            return false;
        }
        
        const config = await response.json();
        
        if (config.scoreForRound && Array.isArray(config.scoreForRound)) {
            SCORE_FOR_ROUND = config.scoreForRound;
        }
        if (config.seedFactor && Array.isArray(config.seedFactor)) {
            SEED_FACTOR = config.seedFactor;
        }
        if (config.roundNames && Array.isArray(config.roundNames)) {
            ROUND_NAMES = config.roundNames;
        }
        if (config.starBonus && Array.isArray(config.starBonus)) {
            STAR_BONUS = config.starBonus;
        }
        if (config.scoreDiffBuckets && Array.isArray(config.scoreDiffBuckets)) {
            SCORE_DIFF_BUCKETS = config.scoreDiffBuckets;
        }
        
        configLoaded = true;
        console.log('Loaded scoring config:', { SCORE_FOR_ROUND, SEED_FACTOR, ROUND_NAMES, STAR_BONUS, SCORE_DIFF_BUCKETS });
        
        // Also load region positions from the same directory
        const configDir = configPath.substring(0, configPath.lastIndexOf('/'));
        await loadRegionPositions(`${configDir}/regionPositions.json`);
        
        return true;
    } catch (err) {
        console.warn('Error loading scoring config, using defaults:', err);
        return false;
    }
}

// Region positioning - defaults match 2026 bracket layout
// Also loaded from regionPositions.json if available (for Python script compatibility)
export let regionPositions = {
    topLeft: 'East',
    bottomLeft: 'South',
    topRight: 'West',
    bottomRight: 'Midwest'
};

/**
 * Load region positions from a JSON config file.
 * This ensures a single source of truth shared with Python scripts.
 */
export async function loadRegionPositions(configPath = '/marchMadness/2026/regionPositions.json') {
    try {
        const response = await fetch(configPath);
        if (response.ok) {
            const positions = await response.json();
            // Mutate the existing object (don't reassign) so imports stay in sync
            if (positions.topLeft) regionPositions.topLeft = positions.topLeft;
            if (positions.bottomLeft) regionPositions.bottomLeft = positions.bottomLeft;
            if (positions.topRight) regionPositions.topRight = positions.topRight;
            if (positions.bottomRight) regionPositions.bottomRight = positions.bottomRight;
            console.log('Loaded region positions:', regionPositions);
            return true;
        }
    } catch (e) {
        console.log('Using default region positions');
    }
    return false;
}

// Standard tournament matchups: 1v16, 8v9, 5v12, 4v13, 6v11, 3v14, 7v10, 2v15
export const matchupPairs = [
    [1, 16],
    [8, 9],
    [5, 12],
    [4, 13],
    [6, 11],
    [3, 14],
    [7, 10],
    [2, 15]
];

// Excel cell mappings for reading/writing brackets
export const CELL_MAPPINGS = {
    // Left side rows (East top, West bottom)
    leftR1Rows: {
        top: [7, 11, 15, 19, 23, 27, 31, 35],      // East Round 1
        bottom: [42, 46, 50, 54, 58, 62, 66, 70]   // West Round 1
    },
    leftR2Rows: {
        top: [8, 12, 16, 20, 24, 28, 32, 36],      // East Round 2
        bottom: [43, 47, 51, 55, 59, 63, 67, 71]   // West Round 2
    },
