        bottom: [49, 65]                            // Midwest Elite 8
    },
    rightF4Rows: {
        top: 22,                                    // South Final Four
        bottom: 57                                  // Midwest Final Four
    },
    
    // Column letters
    columns: {
        leftSeed: 'B',
        leftTeam: 'C',
        leftR2: 'E',
        leftS16: 'H',
        leftE8: 'K',
        leftF4: 'N',
        championship: 'R',
        champTeam1: 'O',
        champTeam2: 'W',
        rightF4: 'AA',
        rightE8: 'AD',
        rightS16: 'AG',
        rightR2: 'AJ',
        rightTeam: 'AL',
        rightSeed: 'AM',
        // Score columns (placed between team name and next round, toward center)
        leftR1Score: 'D',      // Score for Round 1 teams (next to C)
        leftR2Score: 'F',      // Score for Round 2 winners (next to E)
        leftS16Score: 'I',     // Score for Sweet 16 winners (next to H)
        leftE8Score: 'L',      // Score for Elite 8 winners (next to K)
        leftF4Score: 'O',      // Score for Final Four winners (next to N) - rows 22, 57
        champTeam1Score: 'P',  // Score for Championship Team 1 (row 39)
        champTeam2Score: 'V',  // Score for Championship Team 2 (row 39)
        champWinnerScore: 'S', // Score for Championship winner (row 44)
        rightF4Score: 'Z',     // Score for Final Four winners (next to AA)
        rightE8Score: 'AC',    // Score for Elite 8 winners (next to AD)
        rightS16Score: 'AF',   // Score for Sweet 16 winners (next to AG)
        rightR2Score: 'AI',    // Score for Round 2 winners (next to AJ)
        rightR1Score: 'AK'     // Score for Round 1 teams (next to AL)
    },
    
    // Championship rows
    championship: {
        team1Row: 39,  // O39
        team2Row: 39,  // W39
        winnerRow: 44  // R44
    }
};

// Game structure that maps game IDs to their parent games and positions
// This defines the bracket tree structure
export const BRACKET_STRUCTURE = {
    // Round 1 games (32 games total, 8 per region)
    // Index 0-7: East, 8-15: West, 16-23: South, 24-31: Midwest
    round1: {
        gamesPerRegion: 8,
        regions: ['East', 'West', 'South', 'Midwest'],
        // Maps to round 2: games 0,1 -> r2[0], games 2,3 -> r2[1], etc.
        advancesTo: (gameIndex) => Math.floor(gameIndex / 2)
    },
    
    // Round 2 games (16 games total, 4 per region)
    round2: {
        gamesPerRegion: 4,
        advancesTo: (gameIndex) => Math.floor(gameIndex / 2)
    },
    
    // Sweet 16 (8 games total, 2 per region)
    round3: {
        gamesPerRegion: 2,
        advancesTo: (gameIndex) => Math.floor(gameIndex / 2)
    },
    
    // Elite 8 (4 games total, 1 per region)
    round4: {
        gamesPerRegion: 1,
        // Elite 8 advances to Final Four
        // Games 0 (East) and 1 (West) -> F4 game 0
        // Games 2 (South) and 3 (Midwest) -> F4 game 1
        advancesTo: (gameIndex) => Math.floor(gameIndex / 2)
    },
    
    // Final Four (2 games)
    round5: {
        games: 2,
        advancesTo: () => 0  // Both advance to championship
    },
    
    // Championship (1 game)
    round6: {
        games: 1
    }
};

/**
 * Initialize an empty bracket structure
 */
export function createEmptyBracket() {
    return {
        round1: Array(32).fill(null).map((_, i) => ({
            team1: null,
            team2: null,
            winner: null,
            gameId: `r1-${i}`,
            round: 1
        })),
        round2: Array(16).fill(null).map((_, i) => ({
            team1: null,
            team2: null,
            winner: null,
            gameId: `r2-${i}`,
            round: 2
        })),
        round3: Array(8).fill(null).map((_, i) => ({
            team1: null,
            team2: null,
            winner: null,
            gameId: `r3-${i}`,
            round: 3
        })),
        round4: Array(4).fill(null).map((_, i) => ({
            team1: null,
            team2: null,
            winner: null,
            gameId: `r4-${i}`,
            round: 4
        })),
        round5: Array(2).fill(null).map((_, i) => ({
            team1: null,
            team2: null,
            winner: null,
            gameId: `r5-${i}`,
            round: 5
        })),
        round6: [{
            team1: null,
            team2: null,
            winner: null,
            gameId: 'r6-0',
            round: 6
        }],
        winner: null
    };
}

/**
 * Initialize bracket with teams from CSV data
 */
export function initializeBracketWithTeams(teams) {
    const bracket = createEmptyBracket();
    
    // Group teams by region
    const regions = {
        East: [],
        West: [],
        South: [],
        Midwest: []
    };
    
    teams.forEach(team => {
        if (regions[team.region]) {
            regions[team.region].push(team);
        }
    });
    
    // Sort each region by seed
    Object.keys(regions).forEach(region => {
        regions[region].sort((a, b) => a.seed - b.seed);
    });
    
    // Process regions in order: East, West, South, Midwest
    const orderedRegions = [
        regionPositions.topLeft,     // East
        regionPositions.bottomLeft,  // West
        regionPositions.topRight,    // South
        regionPositions.bottomRight  // Midwest
    ];
    
    let gameIndex = 0;
    orderedRegions.forEach(regionName => {
        const regionTeams = regions[regionName];
        
        matchupPairs.forEach(([seed1, seed2]) => {
            const team1 = regionTeams.find(t => t.seed === seed1);
            const team2 = regionTeams.find(t => t.seed === seed2);
            
            if (team1 && team2) {
                bracket.round1[gameIndex] = {
                    team1: team1,
                    team2: team2,
                    winner: null,
                    region: regionName,
                    gameId: `r1-${regionName}-${seed1}v${seed2}`,
                    round: 1
                };
            }
            gameIndex++;
        });
    });
    
    return bracket;
}

/**
 * Get the region for a game based on its index and round
 */
export function getRegionForGame(round, gameIndex) {
    if (round === 1) {
        if (gameIndex < 8) return 'East';
        if (gameIndex < 16) return 'West';
        if (gameIndex < 24) return 'South';
        return 'Midwest';
    } else if (round === 2) {
        if (gameIndex < 4) return 'East';
        if (gameIndex < 8) return 'West';
        if (gameIndex < 12) return 'South';
        return 'Midwest';
    } else if (round === 3) {
        if (gameIndex < 2) return 'East';
        if (gameIndex < 4) return 'West';
        if (gameIndex < 6) return 'South';
        return 'Midwest';
    } else if (round === 4) {
        if (gameIndex === 0) return 'East';
        if (gameIndex === 1) return 'West';
        if (gameIndex === 2) return 'South';
        return 'Midwest';
    }
    return 'Finals';
}

/**
 * Compute score for a bracket against results
 * @param {Object} resultsBracket - The official results bracket
 * @param {Object} picksBracket - The user's picks bracket
 * @param {Object} teamsData - Map of team names to their data (for seeds)
 * @param {Object} options - Scoring options
 */
export function computeScore(resultsBracket, picksBracket, teamsData, options = {}) {
    const {
        scoringVector = SCORE_FOR_ROUND,
        rounds = new Set([1, 2, 3, 4, 5, 6]),
        applySeedBonus = true
    } = options;
    
    let totalScore = 0;
    let correctPicks = 0;
    let seedBonus = 0;  // Track seed bonus separately
    let roundBreakdown = [0, 0, 0, 0, 0, 0, 0]; // Index by round
    
    // Iterate through all rounds
    for (let round = 1; round <= 6; round++) {
        if (!rounds.has(round)) continue;
        
        const roundKey = `round${round}`;
        const resultsRound = resultsBracket[roundKey];
        const picksRound = picksBracket[roundKey];
        
        if (!resultsRound || !picksRound) continue;
        
        resultsRound.forEach((resultGame, index) => {
            const pickGame = picksRound[index];
            
            if (!resultGame || !pickGame) return;
            if (!resultGame.winner || !pickGame.winner) return;
            
            // Check if pick matches result
            if (resultGame.winner.name === pickGame.winner.name) {
                const points = scoringVector[round];
                totalScore += points;
                roundBreakdown[round] += points;
                correctPicks++;
                
                // Apply upset bonus if enabled
                if (applySeedBonus && resultGame.team1 && resultGame.team2) {
                    const team1Seed = teamsData[resultGame.team1.name]?.seed || resultGame.team1.seed;
                    const team2Seed = teamsData[resultGame.team2.name]?.seed || resultGame.team2.seed;
                    const winnerSeed = teamsData[resultGame.winner.name]?.seed || resultGame.winner.seed;
                    
                    // Upset bonus: if higher seed (larger number) wins
                    const expectedWinnerSeed = Math.min(team1Seed, team2Seed);
                    if (winnerSeed > expectedWinnerSeed) {
                        const upsetBonus = (winnerSeed - expectedWinnerSeed) * SEED_FACTOR[round];
                        totalScore += upsetBonus;
                        seedBonus += upsetBonus;
                        roundBreakdown[round] += upsetBonus;
                    }
                }
            }
        });
    }
    
    return {
        totalScore,
        correctPicks,
        seedBonus,
        roundBreakdown
    };
}

/**
 * Compute remaining possible points for a bracket, including potential seed bonuses.
 * @param {Object} resultsBracket - The official results bracket
 * @param {Object} picksBracket - The user's picks bracket
 * @param {Object} teamsData - Map of team names to their data (for seeds)
 * @returns {Object} { basePoints, bonusPoints, total }
 */
export function computePossibleRemaining(resultsBracket, picksBracket, teamsData) {
    let basePoints = 0;
    let bonusPoints = 0;
    
    // Find teams still alive in the tournament
    const remainingTeams = new Set();
    
    for (let round = 1; round <= 6; round++) {
        const roundKey = `round${round}`;
        const resultsRound = resultsBracket[roundKey];
        
        if (!resultsRound) continue;
        
        resultsRound.forEach(game => {
            if (!game) return;
            
            // If game hasn't been played yet
            if (!game.winner) {
                if (game.team1) remainingTeams.add(game.team1.name);
                if (game.team2) remainingTeams.add(game.team2.name);
            }
        });
    }
    
    // Calculate possible points from remaining games
    for (let round = 1; round <= 6; round++) {
        const roundKey = `round${round}`;
        const resultsRound = resultsBracket[roundKey];
        const picksRound = picksBracket[roundKey];
        
        if (!resultsRound || !picksRound) continue;
        
        resultsRound.forEach((resultGame, index) => {
            const pickGame = picksRound[index];
            
            if (!resultGame || !pickGame) return;
            
            // If game hasn't been decided yet and user's pick is still alive
            if (!resultGame.winner && pickGame.winner && remainingTeams.has(pickGame.winner.name)) {
                // Add base points for this round
                basePoints += SCORE_FOR_ROUND[round];
                
                // Calculate potential seed bonus: MAX(0, seed_chosen - seed_opponent) * SEED_FACTOR[round]
                if (resultGame.team1 && resultGame.team2) {
                    const pickName = pickGame.winner.name;
                    const team1Name = resultGame.team1.name;
                    const team2Name = resultGame.team2.name;
                    
                    const pickSeed = teamsData[pickName]?.seed || pickGame.winner.seed;
                    const opponentName = (pickName === team1Name) ? team2Name : team1Name;
                    const opponentSeed = teamsData[opponentName]?.seed || 
                        (pickName === team1Name ? resultGame.team2.seed : resultGame.team1.seed);
                    
                    if (pickSeed && opponentSeed && pickSeed > opponentSeed) {
                        bonusPoints += (pickSeed - opponentSeed) * SEED_FACTOR[round];
                    }
                }
            }
        });
    }
    
    return { basePoints, bonusPoints, total: basePoints + bonusPoints };
}

/**
 * Compute stake in a specific game for a bracket
 * Returns how many points are riding on each team winning
 */
export function computeStakeInGame(resultsBracket, picksBracket, round, gameIndex) {
    const roundKey = `round${round}`;
    const resultGame = resultsBracket[roundKey]?.[gameIndex];
    const pickGame = picksBracket[roundKey]?.[gameIndex];
    
    if (!resultGame || !pickGame) return null;
    if (!resultGame.team1 || !resultGame.team2) return null;
    
    const team1Name = resultGame.team1.name;
    const team2Name = resultGame.team2.name;
    const pickedWinner = pickGame.winner?.name;
    
    if (!pickedWinner) return { team1: 0, team2: 0, hasPick: false };
    
    const pickIsTeam1 = pickedWinner === team1Name;
    const pickIsTeam2 = pickedWinner === team2Name;
    
    // If user picked neither team (their pick was eliminated earlier), they have no stake
    if (!pickIsTeam1 && !pickIsTeam2) {
        return { team1: 0, team2: 0, hasPick: false, pickedTeam: pickedWinner };
    }
    
    // Calculate total stake: sum of points for this round + all future rounds
    // where the user has this team advancing
    const teamToCheck = pickIsTeam1 ? team1Name : team2Name;
    let totalStake = 0;
    
    // Add points for current round
    totalStake += SCORE_FOR_ROUND[round];
    
    // Check future rounds to see how far the user has this team advancing
    for (let futureRound = round + 1; futureRound <= 6; futureRound++) {
        const futureRoundKey = `round${futureRound}`;
        const futureGames = picksBracket[futureRoundKey];
        
        if (!futureGames) break;
        
        // Check if the team appears as a winner in any game of this future round
        let teamAdvances = false;
        for (const game of futureGames) {
            if (game && game.winner && game.winner.name === teamToCheck) {
                teamAdvances = true;
                break;
            }
        }
        
        if (teamAdvances) {
            totalStake += SCORE_FOR_ROUND[futureRound];
        } else {
            // Team doesn't advance past this round in user's bracket
            break;
        }
    }
    
    // Also check if user has this team as the overall winner
    if (picksBracket.winner && picksBracket.winner.name === teamToCheck) {
        // Winner points are included in round 6, so no extra addition needed
    }
    
    return {
        team1: pickIsTeam1 ? totalStake : 0,
        team2: pickIsTeam2 ? totalStake : 0,
        hasPick: true,
        pickedTeam: pickedWinner
    };
}

/**
 * Letter to column number conversion (for Excel parsing)
 */
export function letterToNumber(letter) {
    const letters = ['a','b','c','d','e','f','g','h','i','j','k','l','m','n','o','p','q','r','s','t','u','v','w','x','y','z'];
    const lowerLetter = letter.toLowerCase();
    
    if (lowerLetter.length === 1) {
        return letters.indexOf(lowerLetter);
    } else if (lowerLetter.length === 2) {
        // Handle two-letter columns like 'AA', 'AL', etc.
        const first = letters.indexOf(lowerLetter[0]);
        const second = letters.indexOf(lowerLetter[1]);
        return (first + 1) * 26 + second;
    }
    return -1;
}

/**
 * Column number to letter conversion
 */
export function numberToLetter(num) {
    const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    if (num < 26) {
        return letters[num];
    } else {
        const first = Math.floor(num / 26) - 1;
        const second = num % 26;
        return letters[first] + letters[second];
    }
}

// Bracket I/O utilities for loading and saving bracket files
// Supports both JSON (preferred) and Excel formats

import { regionPositions, matchupPairs } from './BracketStructure.js';

// Re-export so existing imports from bracketIO.js continue to work
export { regionPositions, matchupPairs };

/**
 * Load teams from CSV file
 * @param {string} path - Path to the CSV file
 * @returns {Promise<{teams: Object, teamsList: Array}>}
 */
export async function loadTeamsFromCSV(path) {
    const response = await fetch(path);
    
    if (!response.ok) {
        throw new Error(`Failed to load teams CSV: ${response.status}`);
    }
    
    const csvText = await response.text();
    const lines = csvText.trim().split('\n');
    
    // Skip header row
    const dataLines = lines.slice(1);
    
    const teams = {};
    const teamsList = dataLines.map(line => {
        const [team, seed, region] = line.split(',').map(s => s.trim());
        const teamObj = {
            name: team,
            seed: parseInt(seed),
            region: region
        };
        teams[team] = teamObj;
        return teamObj;
    });
    
    return { teams, teamsList };
}

/**
 * Initialize an empty bracket structure with teams
 * @param {Array} teamsList - List of team objects
 * @returns {Object} - Initialized bracket
 */
export function initializeBracket(teamsList) {
    const bracket = {
        round1: [],
        round2: [],
        round3: [],
        round4: [],
        round5: [],
        round6: [],
        winner: null
    };
    
    // Group teams by region
    const regions = {
        East: [],
        West: [],
        South: [],
        Midwest: []
    };
    
    teamsList.forEach(team => {
        if (regions[team.region]) {
            regions[team.region].push(team);
        }
    });
    
    // Sort each region by seed
    Object.keys(regions).forEach(region => {
        regions[region].sort((a, b) => a.seed - b.seed);
    });
    
    // Process regions in order based on positioning
    const orderedRegions = [
        regionPositions.topLeft,
        regionPositions.bottomLeft,
        regionPositions.topRight,
        regionPositions.bottomRight
    ];
    
    // Round 1 - no parent games
    orderedRegions.forEach(regionName => {
        const regionTeams = regions[regionName];
        
        matchupPairs.forEach(([seed1, seed2]) => {
            const team1 = regionTeams.find(t => t.seed === seed1);
            const team2 = regionTeams.find(t => t.seed === seed2);
            
            if (team1 && team2) {
                bracket.round1.push({
                    team1: team1,
                    team2: team2,
                    winner: null,
                    region: regionName,
                    parentGames: null,
                    gameId: `r1-${regionName}-${seed1}v${seed2}`
                });
            }
        });
    });
    
    // Round 2 - parents are pairs of Round 1 games
    bracket.round2 = Array(16).fill(null).map((_, i) => ({
        team1: null,
        team2: null,
        winner: null,
        parentGames: [bracket.round1[i * 2], bracket.round1[i * 2 + 1]],
        gameId: `r2-${i}`
    }));
    
    // Round 3 (Sweet 16)
    bracket.round3 = Array(8).fill(null).map((_, i) => ({
        team1: null,
        team2: null,
        winner: null,
        parentGames: [bracket.round2[i * 2], bracket.round2[i * 2 + 1]],
        gameId: `r3-${i}`
    }));
    
    // Round 4 (Elite 8)
    bracket.round4 = Array(4).fill(null).map((_, i) => ({
        team1: null,
        team2: null,
        winner: null,
        parentGames: [bracket.round3[i * 2], bracket.round3[i * 2 + 1]],
        gameId: `r4-${i}`
    }));
    
    // Round 5 (Final Four)
    bracket.round5 = [
        { 
            team1: null, 
            team2: null, 
            winner: null, 
            parentGames: [bracket.round4[0], bracket.round4[1]],
            gameId: 'semifinal-left' 
        },
        { 
            team1: null, 
            team2: null, 
            winner: null, 
            parentGames: [bracket.round4[2], bracket.round4[3]],
            gameId: 'semifinal-right' 
        }
    ];
    
    // Round 6 (Championship)
    bracket.round6 = [{
        team1: null,
        team2: null,
        winner: null,
        parentGames: [bracket.round5[0], bracket.round5[1]],
        gameId: 'championship'
    }];
    
    return bracket;
}

/**
 * Load bracket from JSON file
 * @param {string} path - Path to JSON file
 * @param {Object} teams - Teams lookup object (optional, for enriching data)
 * @returns {Promise<Object>} - Bracket object
 */
export async function loadBracketFromJSON(path, teams = null) {
    const response = await fetch(path);
    
    if (!response.ok) {
        throw new Error(`Failed to load bracket JSON: ${response.status}`);
    }
    
    const bracket = await response.json();
    
    // Optionally enrich team data with full team info
    if (teams) {
        enrichBracketTeams(bracket, teams);
    }
    
    // Add parentGames references for UI navigation
    addParentGameReferences(bracket);
    
    return bracket;
}

/**
 * Enrich bracket team data with full team info from teams lookup
 */
function enrichBracketTeams(bracket, teams) {
    const enrichTeam = (team) => {
        if (!team || !team.name) return team;
        const fullTeam = teams[team.name];
        if (fullTeam) {
            return { ...team, ...fullTeam };
        }
        return team;
    };
    
    const enrichGame = (game) => {
        if (!game) return game;
        game.team1 = enrichTeam(game.team1);
        game.team2 = enrichTeam(game.team2);
        game.winner = enrichTeam(game.winner);
        return game;
    };
    
    for (let round = 1; round <= 6; round++) {
        const roundKey = `round${round}`;
        if (bracket[roundKey]) {
            bracket[roundKey].forEach(enrichGame);
        }
    }
    
    if (bracket.winner) {
        bracket.winner = enrichTeam(bracket.winner);
    }
}

/**
 * Add parentGames references for UI navigation between rounds
 */
function addParentGameReferences(bracket) {
    // Round 2 parents are Round 1 game pairs
    if (bracket.round2) {
        bracket.round2.forEach((game, i) => {
            if (game && bracket.round1) {
                game.parentGames = [bracket.round1[i * 2], bracket.round1[i * 2 + 1]];
            }
        });
    }
    
    // Round 3 parents are Round 2 game pairs
    if (bracket.round3) {
        bracket.round3.forEach((game, i) => {
            if (game && bracket.round2) {
                game.parentGames = [bracket.round2[i * 2], bracket.round2[i * 2 + 1]];
            }
        });
    }
    
    // Round 4 parents are Round 3 game pairs
    if (bracket.round4) {
        bracket.round4.forEach((game, i) => {
            if (game && bracket.round3) {
                game.parentGames = [bracket.round3[i * 2], bracket.round3[i * 2 + 1]];
            }
        });
    }
    
    // Round 5 (Final Four)
    if (bracket.round5 && bracket.round4) {
        if (bracket.round5[0]) {
            bracket.round5[0].parentGames = [bracket.round4[0], bracket.round4[1]];
        }
        if (bracket.round5[1]) {
            bracket.round5[1].parentGames = [bracket.round4[2], bracket.round4[3]];
        }
    }
    
    // Round 6 (Championship)
    if (bracket.round6 && bracket.round6[0] && bracket.round5) {
        bracket.round6[0].parentGames = [bracket.round5[0], bracket.round5[1]];
    }
}

/**
 * Save bracket to JSON file (triggers download)
 * @param {Object} bracket - Bracket object to save
 * @param {string} filename - Filename for download
 */
export function saveBracketToJSON(bracket, filename = 'bracket.json') {
    // Create clean version without circular references (parentGames)
    const cleanBracket = cleanBracketForExport(bracket);
    
    const jsonStr = JSON.stringify(cleanBracket, null, 2);
    const blob = new Blob([jsonStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
}

/**
 * Clean bracket for export (remove circular refs, keep only essential data)
 */
function cleanBracketForExport(bracket) {
    const cleanTeam = (team) => {
        if (!team) return null;
        return {
            name: team.name,
            seed: team.seed,
            region: team.region || ''
        };
    };
    
    const cleanGame = (game) => {
        if (!game) return null;
        return {
            team1: cleanTeam(game.team1),
            team2: cleanTeam(game.team2),
            winner: cleanTeam(game.winner),
            gameId: game.gameId || '',
            region: game.region || ''
        };
    };
    
    return {
        round1: bracket.round1?.map(cleanGame) || [],
        round2: bracket.round2?.map(cleanGame) || [],
        round3: bracket.round3?.map(cleanGame) || [],
        round4: bracket.round4?.map(cleanGame) || [],
        round5: bracket.round5?.map(cleanGame) || [],
        round6: bracket.round6?.map(cleanGame) || [],
        winner: cleanTeam(bracket.winner)
    };
}

/**
 * Load bracket from path, trying JSON first, then Excel
 * @param {string} basePath - Base path without extension
 * @param {Object} teams - Teams lookup object
 * @param {Array} teamsList - List of team objects (for Excel fallback)
 * @returns {Promise<Object>} - Bracket object
 */
export async function loadBracketFromPath(basePath, teams = null, teamsList = null) {
    // Remove any existing extension
    const pathWithoutExt = basePath.replace(/\.(json|xlsx|csv)$/, '');
    
    // Generate case variants of the path
    const lastSlash = pathWithoutExt.lastIndexOf('/');
    const dir = lastSlash >= 0 ? pathWithoutExt.substring(0, lastSlash) : '';
    const filename = lastSlash >= 0 ? pathWithoutExt.substring(lastSlash + 1) : pathWithoutExt;
    
    // Generate filename variants (case)
    const caseVariants = [filename];
    const lower = filename.toLowerCase();
    const dashIdx = filename.indexOf('-');
    const namePart = dashIdx >= 0 ? filename.substring(0, dashIdx) : filename;
    const rest = dashIdx >= 0 ? filename.substring(dashIdx) : '';
    const nameCapitalized = namePart.charAt(0).toUpperCase() + namePart.slice(1).toLowerCase() + rest;
    
    if (lower !== filename) caseVariants.push(lower);
    if (nameCapitalized !== filename && !caseVariants.includes(nameCapitalized)) caseVariants.push(nameCapitalized);
    
    // Also try alternate filename pattern: swap "bracket-march-madness" with "march-madness-bracket"
    const allVariants = [];
    for (const variant of caseVariants) {
        allVariants.push(variant);
        if (variant.includes('-bracket-march-madness-')) {
            allVariants.push(variant.replace('-bracket-march-madness-', '-march-madness-bracket-'));
        } else if (variant.includes('-march-madness-bracket-')) {
            allVariants.push(variant.replace('-march-madness-bracket-', '-bracket-march-madness-'));
        }
    }
    
    for (const variant of allVariants) {
        const variantPath = dir ? `${dir}/${variant}` : variant;
        
        // Try JSON first
        try {
            const jsonPath = `${variantPath}.json`;
            const response = await fetch(jsonPath, { method: 'HEAD' });
            if (response.ok) {
                return await loadBracketFromJSON(jsonPath, teams);
            }
        } catch (e) {}
        
        // Fall back to Excel
        try {
            const xlsxPath = `${variantPath}.xlsx`;
            const response = await fetch(xlsxPath);
            if (response.ok) {
                const arrayBuffer = await response.arrayBuffer();
                return await loadBracketFromExcel(arrayBuffer, teams, teamsList);
            }
        } catch (e) {}
    }
    
    throw new Error(`Bracket not found at ${basePath} (tried .json and .xlsx with variants: ${allVariants.join(', ')})`);
}

/**
 * Helper to get cell value from Excel sheet
 */
function getCellValue(sheet, col, row) {
    const cell = sheet.getCell(`${col}${row}`);
    let value = cell.value;
    
    if (value && typeof value === 'object' && value.result) {
        value = value.result;
    }
    
    if (typeof value === 'string') {
        return value.trim();
    }
    return value;
}

/**
 * Find a team by name with fuzzy matching
 * @param {string} name - Team name to find
 * @param {Object} teams - Teams lookup object
 * @returns {Object|null} - Team object or null
 */
export function findTeam(name, teams) {
    if (!name) return null;
    const teamName = String(name).trim();
    if (teams[teamName]) {
        return teams[teamName];
    }
    // Try partial match
    for (const [key, team] of Object.entries(teams)) {
        if (key.toLowerCase().includes(teamName.toLowerCase()) || 
            teamName.toLowerCase().includes(key.toLowerCase())) {
            return team;
        }
    }
    // Return a basic team object if not found
    return { name: teamName, seed: 0 };
}

/**
 * Load bracket from Excel ArrayBuffer
 * @param {ArrayBuffer} arrayBuffer - Excel file contents
 * @param {Object} teams - Teams lookup
 * @param {Array} teamsList - Teams list for initialization
 * @returns {Promise<Object>} - Bracket object
 */
export async function loadBracketFromExcel(arrayBuffer, teams, teamsList) {
    const ExcelJSModule = await import('https://cdn.jsdelivr.net/npm/exceljs@4.4.0/+esm');
    const ExcelJS = ExcelJSModule.default || ExcelJSModule;
    
    const workbook = new ExcelJS.Workbook();
    await workbook.xlsx.load(arrayBuffer);
    
    const sheet = workbook.getWorksheet('madness') || workbook.worksheets[0];
    if (!sheet) {
        throw new Error('No worksheet found in Excel file');
    }
    
    // Initialize bracket with teams
    const bracket = initializeBracket(teamsList);
    
    // Extract from each region
    // East (top-left)
    extractRegionWinners(sheet, bracket, 0, {
        r2Rows: [8, 12, 16, 20, 24, 28, 32, 36],
        s16Rows: [10, 18, 26, 34],
        e8Rows: [14, 30],
        f4Row: 22,
        r2Col: 'E', s16Col: 'H', e8Col: 'K', f4Col: 'N'
    }, teams);
    
    // West (bottom-left)
    extractRegionWinners(sheet, bracket, 8, {
        r2Rows: [43, 47, 51, 55, 59, 63, 67, 71],
        s16Rows: [45, 53, 61, 69],
        e8Rows: [49, 65],
        f4Row: 57,
        r2Col: 'E', s16Col: 'H', e8Col: 'K', f4Col: 'N'
    }, teams);
    
    // South (top-right)
    extractRegionWinners(sheet, bracket, 16, {
        r2Rows: [8, 12, 16, 20, 24, 28, 32, 36],
        s16Rows: [10, 18, 26, 34],
        e8Rows: [14, 30],
        f4Row: 22,
        r2Col: 'AJ', s16Col: 'AG', e8Col: 'AD', f4Col: 'AA'
    }, teams);
    
    // Midwest (bottom-right)
    extractRegionWinners(sheet, bracket, 24, {
        r2Rows: [43, 47, 51, 55, 59, 63, 67, 71],
        s16Rows: [45, 53, 61, 69],
        e8Rows: [49, 65],
        f4Row: 57,
        r2Col: 'AJ', s16Col: 'AG', e8Col: 'AD', f4Col: 'AA'
    }, teams);
    
    // Championship
    extractChampionship(sheet, bracket, teams);
    
    return bracket;
}

/**
 * Extract region winners from Excel sheet and populate bracket
 */
function extractRegionWinners(sheet, bracket, startIndex, config, teams) {
    const { r2Rows, s16Rows, e8Rows, f4Row, r2Col, s16Col, e8Col, f4Col } = config;
    
    // Round 1 winners (read from Round 2 cells)
    for (let i = 0; i < 8; i++) {
        const row = r2Rows[i];
        const winnerName = getCellValue(sheet, r2Col, row);
        if (winnerName) {
            const winner = findTeam(winnerName, teams);
            if (winner) {
                bracket.round1[startIndex + i].winner = winner;
                const r2GameIndex = Math.floor((startIndex + i) / 2);
                if ((startIndex + i) % 2 === 0) {
                    bracket.round2[r2GameIndex].team1 = winner;
                } else {
                    bracket.round2[r2GameIndex].team2 = winner;
                }
            }
        }
    }
    
    // Round 2 winners (Sweet 16)
    const r2StartIndex = Math.floor(startIndex / 2);
    for (let i = 0; i < 4; i++) {
        const row = s16Rows[i];
        const winnerName = getCellValue(sheet, s16Col, row);
        if (winnerName) {
            const winner = findTeam(winnerName, teams);
            if (winner) {
                bracket.round2[r2StartIndex + i].winner = winner;
                const r3GameIndex = Math.floor((r2StartIndex + i) / 2);
                if ((r2StartIndex + i) % 2 === 0) {
                    bracket.round3[r3GameIndex].team1 = winner;
                } else {
                    bracket.round3[r3GameIndex].team2 = winner;
                }
            }
        }
    }
    
    // Round 3 winners (Elite 8)
    const r3StartIndex = Math.floor(startIndex / 4);
    for (let i = 0; i < 2; i++) {
        const row = e8Rows[i];
        const winnerName = getCellValue(sheet, e8Col, row);
        if (winnerName) {
            const winner = findTeam(winnerName, teams);
            if (winner) {
                bracket.round3[r3StartIndex + i].winner = winner;
                const r4GameIndex = Math.floor((r3StartIndex + i) / 2);
                if ((r3StartIndex + i) % 2 === 0) {
                    bracket.round4[r4GameIndex].team1 = winner;
                } else {
                    bracket.round4[r4GameIndex].team2 = winner;
                }
            }
        }
    }
    
    // Round 4 winner (Final Four qualifier)
    const r4GameIndex = Math.floor(startIndex / 8);
    const f4WinnerName = getCellValue(sheet, f4Col, f4Row);
    if (f4WinnerName) {
        const winner = findTeam(f4WinnerName, teams);
        if (winner) {
            bracket.round4[r4GameIndex].winner = winner;
            const r5GameIndex = Math.floor(r4GameIndex / 2);
            if (r4GameIndex % 2 === 0) {
                bracket.round5[r5GameIndex].team1 = winner;
            } else {
                bracket.round5[r5GameIndex].team2 = winner;
            }
        }
    }
}

/**
 * Extract championship results from Excel
 */
function extractChampionship(sheet, bracket, teams) {
    // Left semifinal winner (O39)
    const leftWinner = getCellValue(sheet, 'O', 39);
    if (leftWinner) {
        const winner = findTeam(leftWinner, teams);
        if (winner) {
            bracket.round5[0].winner = winner;
            bracket.round6[0].team1 = winner;
        }
    }
    
    // Right semifinal winner (W39)
    const rightWinner = getCellValue(sheet, 'W', 39);
    if (rightWinner) {
        const winner = findTeam(rightWinner, teams);
        if (winner) {
            bracket.round5[1].winner = winner;
            bracket.round6[0].team2 = winner;
        }
    }
    
    // Champion (R44)
    const champion = getCellValue(sheet, 'R', 44);
    if (champion) {
        const winner = findTeam(champion, teams);
        if (winner) {
            bracket.round6[0].winner = winner;
            bracket.winner = winner;
        }
    }
}

